SELECT g.id, g.name_original, g.confidence_score, (SELECT count(*) FROM sources s WHERE s.entity_id=g.id) AS n_src FROM geo_entities g WHERE g.id IN (216, 217, 219, 884, 898, 902, 906, 968, 984, 1009) ORDER BY g.id;
